  const useCases = [
    { label: "Legal", company: "Harvey", desc: "Custom LLMs for elite law firms" },
    { label: "Enterprise Search", company: "Glean", desc: "Crawling & indexing workspaces" },
    { label: "Companionship", company: "Character, Ava", desc: "Digital companions & entertainment" },
  ];

  useCases.forEach((uc, i) => {
    const y = topY + 0.55 + i * 0.85;
    s.addShape(pres.shapes.RECTANGLE, {
      x: rightX, y: y, w: rightW, h: 0.75,
      fill: { color: C.white }, shadow: cardShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: rightX, y: y, w: 0.06, h: 0.75,
      fill: { color: C.teal }
