    s.addText(uc.label, {
      x: rightX + 0.2, y: y + 0.05, w: rightW - 0.3, h: 0.35,
      fontSize: 15, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
    });
    s.addText([
      { text: uc.company, options: { bold: true, fontSize: 11, fontFace: "Calibri", color: C.tealDark } },
      { text: " — " + uc.desc, options: { fontSize: 11, fontFace: "Calibri", color: C.bodyText } },
