const pptxgen = require("pptxgenjs");
const fs = require("fs");

const outDir = "/app/output";
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Sequoia Capital";
pres.title = "Generative AI's Act Two: From Technology Hammer to Real Value";

// ─── Color Palette ───
const C = {
  darkNavy:   "0B1426",
  navy:       "142850",
  teal:       "00B4D8",
  tealDark:   "0891B2",
  tealMuted:  "0E7490",
  tealBg:     "E0F7FA",
  coral:      "E85D3A",
  coralDark:  "C2410C",
  coralBg:    "FFF1ED",
  lightBg:    "F0F2F5",
  white:      "FFFFFF",
  darkText:   "1A1A2E",
  bodyText:   "334155",
  medGray:    "64748B",
  lightGray:  "E2E8F0",
};

// Fresh shadow factory (never reuse objects)
const cardShadow = () => ({
  type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.10
});

// ═══════════════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkNavy };

  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.teal }
  });

  // Decorative line bottom-right
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 4.6, w: 2.5, h: 0.04, fill: { color: C.teal }
  });

  s.addText("Generative AI’s Act Two", {
    x: 1.2, y: 1.4, w: 8, h: 1.1,
    fontSize: 44, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });

  s.addText("From Technology Hammer to Real Value", {
    x: 1.2, y: 2.6, w: 8, h: 0.6,
    fontSize: 24, fontFace: "Georgia", color: C.teal, margin: 0
  });

  s.addText("Sequoia Capital  |  September 2023", {
    x: 1.2, y: 4.0, w: 6, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: C.medGray, margin: 0
  });

  s.addText("Sonya Huang, Pat Grady and GPT-4", {
    x: 1.2, y: 4.35, w: 6, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.medGray, margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════
// SLIDE 2 — DECADES OF CONVERGENCE
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("Six Decades of Technological Progress Converged to Enable Generative AI", {
    x: 0.6, y: 0.4, w: 8.8, h: 0.9,
    fontSize: 21, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
  });

  const cards = [
    { years: "60", label: "YEARS", title: "Moore’s Law", desc: "Delivered the compute horsepower to process exaflops of data", color: C.teal },
    { years: "40", label: "YEARS", title: "The Internet", desc: "Produced trillions of tokens of training data, accelerated by COVID", color: C.tealDark },
    { years: "20", label: "YEARS", title: "Mobile & Cloud", desc: "Put a supercomputer in every human’s palm", color: C.navy },
  ];

  const startY = 1.45;
  const cardH = 1.05;
  const gap = 0.15;

  cards.forEach((card, i) => {
    const y = startY + i * (cardH + gap);

    // Card background
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: y, w: 8.8, h: cardH,
      fill: { color: C.white }, shadow: cardShadow()
    });

    // Left colored block
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: y, w: 1.6, h: cardH,
      fill: { color: card.color }
    });

    // Big number
    s.addText(card.years, {
      x: 0.6, y: y + 0.05, w: 1.6, h: 0.6,
      fontSize: 34, fontFace: "Georgia", color: C.white, bold: true, align: "center", margin: 0
    });

    // "YEARS" label
    s.addText(card.label, {
      x: 0.6, y: y + 0.65, w: 1.6, h: 0.3,
      fontSize: 10, fontFace: "Calibri", color: C.white, align: "center", charSpacing: 3, margin: 0
    });

    // Title
    s.addText(card.title, {
      x: 2.5, y: y + 0.1, w: 6.7, h: 0.4,
      fontSize: 19, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
    });

    // Description
    s.addText(card.desc, {
      x: 2.5, y: y + 0.5, w: 6.7, h: 0.45,
      fontSize: 13, fontFace: "Calibri", color: C.bodyText, margin: 0
    });
  });

  // Bottom annotation
  s.addText("ChatGPT’s launch ignited a Cambrian explosion of innovation not seen since the early internet.", {
    x: 0.6, y: 5.0, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: "Calibri", color: C.medGray, italic: true, margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════
// SLIDE 3 — GENAI OUTPACES SAAS
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did", {
    x: 0.6, y: 0.35, w: 8.8, h: 0.85,
    fontSize: 21, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
  });

  // Big stat callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.35, w: 8.8, h: 1.4,
    fill: { color: C.darkNavy }
  });

  s.addText(">$1B", {
    x: 0.6, y: 1.38, w: 8.8, h: 0.9,
    fontSize: 56, fontFace: "Georgia", color: C.teal, bold: true, align: "center", margin: 0
  });

  s.addText("startup revenue in months — a milestone that took SaaS years, not months, to reach", {
    x: 0.6, y: 2.3, w: 8.8, h: 0.4,
    fontSize: 13, fontFace: "Calibri", color: C.white, align: "center", margin: 0
  });

  // Three standout cards
  const examples = [
    { name: "ChatGPT", stat: "Fastest-growing app in history", detail: "Strong product-market fit among students and developers", accent: C.teal },
    { name: "Midjourney", stat: "Hundreds of millions in revenue", detail: "With a team of just 11 people", accent: C.tealDark },
    { name: "Character.ai", stat: "2-hour average session time", detail: "Popularized AI entertainment and companionship", accent: C.navy },
  ];

  const cardW = 2.73;
  const cardGap = 0.3;
  const cardStartX = 0.6;
  const cardY = 3.0;
  const cardH = 2.1;

  examples.forEach((ex, i) => {
    const x = cardStartX + i * (cardW + cardGap);

    // Card background
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.white }, shadow: cardShadow()
    });

    // Top accent bar
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: cardY, w: cardW, h: 0.06, fill: { color: ex.accent }
    });

    // Company name
    s.addText(ex.name, {
      x: x + 0.2, y: cardY + 0.2, w: cardW - 0.4, h: 0.35,
      fontSize: 18, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
    });

    // Big stat
    s.addText(ex.stat, {
      x: x + 0.2, y: cardY + 0.6, w: cardW - 0.4, h: 0.6,
      fontSize: 15, fontFace: "Georgia", color: ex.accent, bold: true, margin: 0
    });

    // Detail
    s.addText(ex.detail, {
      x: x + 0.2, y: cardY + 1.3, w: cardW - 0.4, h: 0.65,
      fontSize: 12, fontFace: "Calibri", color: C.bodyText, margin: 0
    });
  });
}

// ═══════════════════════════════════════════════════════════════
// SLIDE 4 — RETENTION GAP (Side-by-side bar chart)
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("AI-First Apps Show 14% Median Retention vs. 51% for Incumbents", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 20, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
  });

  // Section headers - aligned with chart x positions
  s.addText("INCUMBENTS", {
    x: 0.5, y: 0.95, w: 4.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.tealDark, bold: true, charSpacing: 2, margin: 0
  });

  s.addText("AI-FIRST COMPANIES", {
    x: 5.2, y: 0.95, w: 4.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.coralDark, bold: true, charSpacing: 2, margin: 0
  });

  // Incumbent retention chart (horizontal bars)
  s.addChart(pres.charts.BAR, [{
    name: "Retention",
    labels: ["WhatsApp", "Instagram", "YouTube", "TikTok", "Snapchat", "Roblox", "Tinder", "Candy Crush", "Duolingo"],
    values: [85, 64, 64, 60, 51, 41, 34, 32, 30]
  }], {
    x: 0.5, y: 1.30, w: 4.3, h: 3.4,
    barDir: "bar",
    chartColors: [C.teal],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 9,
    showLegend: false,
    showTitle: false,
    catAxisLabelColor: C.bodyText,
    catAxisLabelFontSize: 9,
    valAxisHidden: true,
    valGridLine: { style: "none" },
    catGridLine: { style: "none" },
    valAxisMaxVal: 100,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    barGapWidthPct: 40,
  });

  // AI-First retention chart
  s.addChart(pres.charts.BAR, [{
    name: "Retention",
    labels: ["Character.ai", "Runway", "Remini", "ChatGPT", "Lensa"],
    values: [41, 27, 14, 14, 12]
  }], {
    x: 5.2, y: 1.30, w: 4.3, h: 3.4,
    barDir: "bar",
    chartColors: [C.coral],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 9,
    showLegend: false,
    showTitle: false,
    catAxisLabelColor: C.bodyText,
    catAxisLabelFontSize: 9,
    valAxisHidden: true,
    valGridLine: { style: "none" },
    catGridLine: { style: "none" },
    valAxisMaxVal: 100,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    barGapWidthPct: 60,
  });

  // Median callout boxes
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 4.3, h: 0.4,
    fill: { color: C.tealBg }
  });
  s.addText("Median: 51%", {
    x: 0.5, y: 4.85, w: 4.3, h: 0.4,
    fontSize: 13, fontFace: "Calibri", color: C.tealDark, bold: true, align: "center", valign: "middle", margin: 0
  });

  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 4.85, w: 4.3, h: 0.4,
    fill: { color: C.coralBg }
  });
  s.addText("Median: 14%  —  a 3.6× gap", {
    x: 5.2, y: 4.85, w: 4.3, h: 0.4,
    fontSize: 13, fontFace: "Calibri", color: C.coralDark, bold: true, align: "center", valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════
// SLIDE 5 — INCUMBENT MONTHLY USAGE
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("YouTube Leads Incumbents at 85% Monthly Active Usage", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 21, fontFace: "Georgia", color: C.darkText, bold: true, margin: 0
  });

  s.addText("Monthly active usage rates for top consumer apps — the high bar AI apps must clear", {
    x: 0.5, y: 0.90, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.medGray, margin: 0
  });

  // Single horizontal bar chart
  s.addChart(pres.charts.BAR, [{
    name: "Monthly Active Usage",
    labels: ["YouTube", "Instagram", "TikTok", "Snapchat", "WhatsApp", "Roblox", "Tinder", "Duolingo", "Candy Crush"],
    values: [85, 73, 69, 67, 63, 61, 54, 50, 48]
  }], {
    x: 0.5, y: 1.35, w: 7.5, h: 3.4,
    barDir: "bar",
    chartColors: [C.navy],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 10,
    showLegend: false,
    showTitle: false,
    catAxisLabelColor: C.bodyText,
    catAxisLabelFontSize: 10,
    valAxisHidden: true,
    valGridLine: { style: "none" },
    catGridLine: { style: "none" },
    valAxisMaxVal: 100,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    barGapWidthPct: 40,
  });

  // Median callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.9, w: 3, h: 0.35,
    fill: { color: C.darkNavy }
  });
  s.addText("Median: 63%", {
    x: 0.5, y: 4.9, w: 3, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: C.white, bold: true, align: "center", valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════
// SLIDE 6 — ACT 1 VS ACT 2
// ═══════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("Act 1 Was Technology-Out; Act 2 Is Customer-Back", {
    x: 0.5, y: 0.4, w: 9, h: 0.55,
